## 第四部分：错误处理与降级策略

### 1. 全局错误拦截

```typescript
// plugins/error-handler.ts
export default defineNuxtPlugin(() => {
  const config = useRuntimeConfig()

  return {
    provide: {
      fetch: $fetch.create({
        // 请求拦截
        onRequest({ request, options }) {
          // 添加认证头
          const token = useCookie('auth-token').value
          if (token) {
            options.headers = {
              ...options.headers,
              Authorization: `Bearer ${token}`
            }
          }
        },
        // 响应拦截
        onResponse({ response }) {
          // 统一处理业务错误码
          if (response._data?.code !== 200) {
            throw new Error(response._data?.message)
          }
        },
        // 错误处理
        onResponseError({ response }) {
          // 401: 跳转登录
          if (response.status === 401) {
            navigateTo('/login')
          }
          // 404: 记录日志
          if (response.status === 404) {
            console.error('Resource not found:', response.url)
          }
          // 500: 显示友好提示
          if (response.status >= 500) {
            useNotification().error('服务暂时不可用，请稍后重试')
          }
        }
      })
    }
  }
})
```

### 2. 重试机制

```typescript
// 带重试的 useFetch 封装
export function useFetchWithRetry<T>(url: string, options: any = {}) {
  const maxRetries = options.retries ?? 3
  const retryDelay = options.retryDelay ?? 1000

  return useFetch<T>(url, {
    ...options,
    // 重试逻辑
    onResponseError: async ({ response }) => {
      if (response.status >= 500 && options.retryCount < maxRetries) {
        options.retryCount = (options.retryCount || 0) + 1
        // 指数退避
        const delay = retryDelay * Math.pow(2, options.retryCount - 1)
        await new Promise(resolve => setTimeout(resolve, delay))
        // 触发重试
        return refresh()
      }
    }
  })
}

// 使用
const { data, error, refresh } = useFetchWithRetry('/api/products', {
  retries: 3,
  retryDelay: 1000
})
```

